body.usercss:

#NLmFqsdNLmFqsdwWoJ {
    overflow: auto;
}

.menu-filter-icon {
    display:none;
}

.groupbox .menu-filter.inactive .menu-filter-icon{
    display: flex;
    position:absolute;
    bottom: 0px;
    width: 100%;
    justify-content: center;
    cursor:pointer;
}

.summary-component__item:hover{
    transform:translateY(0px);
    box-shadow: none;
}

userscript.function:

$share.data={
    HOUSE_CODE:item.house_code,
    MENU_PROFILE_CODE:item.menu_profile_code
}
clearMenuItem();

doServiceAjax("sepoa.svc.admin.AD_421", "CONNECTION", "doQueryMenuFilter", {
    "HOUSE_CODE": $share.data.HOUSE_CODE,
    "CODE": $share.data.MENU_PROFILE_CODE
}, function(so) {
    var sf = new SepoaFormater(so.result[0]); // All Menu

    var menuItems = {}
    var menuItemsList = [];
    for(var i=0;i<sf.getRowCount();i++) {
        var menuData = {};
        for(var j=0;j<sf.columns.length;j++){
            var columnName = sf.columns;
            menuData[columnName[j]]= sf.getValue(columnName[j],i);
        }
        menuData.childs = [];
        menuItems[menuData.MENU_ID] = menuData;
        menuItemsList.push(menuData);
    }

    var menuTree = [];
    for(var i in menuItemsList){
        var item = menuItemsList[i];
        var parent = item.PARENT_MENU_ID;
        if(parent == "0"){
            menuTree.push(item);
        }else{
            menuItems[item.PARENT_MENU_ID].childs.push(item);
        }
    }

    doRenderMenu(menuTree);
});


for (var i in menuTree) {
    var groupData = menuTree[i];
    var childNodes = groupData.childs;

    if (menuTree[i].HIDDEN_FLAG == "Y") {
        continue;
    }
    if (childNodes.length <= 0) {
        continue;
    }

    const tileRenderer = new SepoaMenuTileRenderer();
    tileRenderer.attachEvent("onItemClick", (option, elem)=>{
        if(elem.classList.contains("inactive")){
            elem.classList.remove("inactive");
        }else{
            elem.classList.add("inactive");
        }
    });
    tileRenderer.attachEvent("onItemDraw", (option, elem)=>{
        elem.classList.add("menu-filter");
        if(option.ext.MENU_FILTERED_YN == "N"){
            elem.classList.add("inactive");   
        }
        const xBtn = elem.appendChild(document.createElement('div'));
        xBtn.classList.add("menu-filter-icon");
        xBtn.innerHTML = '<i class="xi-close xi-5x"></i>'
    });

    for(let j in childNodes){
        const node = childNodes[j];
        if(node.HIDDEN_FLAG != "Y"){
            tileRenderer.addItem({
                id:node.MENU_ID,
                seq:node.ITEM_SEQ,
                label:Sepoa.cache.text.get("MENU_"+node.MENU_PROFILE_CODE+"."+node.MENU_ID),
                url:node.URL,
                mobileUrl:node.MOBILE_URL,
                img:node.MENU_IMG,
                ext:{
                    PARENT_MENU_ID:node.PARENT_MENU_ID,
                    MENU_FILTERED_YN:node.MENU_FILTERED_YN
                }
            });
        }
    }

    if(tileRenderer.getItemCount() > 0){
        const div = menuContainer.appendChild(document.createElement("div"));
        div.classList.add("groupbox");
        tileRenderer.draw({
            base:div,
            label:Sepoa.cache.text.get("MENU_"+groupData.MENU_PROFILE_CODE+"."+groupData.MENU_ID)
        });
    }
}


Confirm(Sepoa.cache.text.get('MESSAGE.1018'), function(result) {
    if (result) {
        const activeList = $('#NLmFqsdGlRJqsddeZO').find('.menu-filter:not(.inactive)');

        const filterData = [];

        for(let i=0;i<activeList.length;i++){
            filterData.push({
                HOUSE_CODE:$share.data.HOUSE_CODE,
                MENU_PROFILE_CODE:$share.data.MENU_PROFILE_CODE,
                MENU_ID:activeList[i].itemOption.id,
                PARENT_ID:activeList[i].itemOption.ext.PARENT_MENU_ID
            })
        }

        dataOutput.setValue('FILTER_DATA', JSON.stringify(filterData));
        dataOutput.setValue('HOUSE_CODE', $share.data.HOUSE_CODE);
        dataOutput.setValue('MENU_PROFILE_CODE', $share.data.MENU_PROFILE_CODE);

        doServiceAjax('sepoa.svc.admin.AD_421', 'TRANSACTION', 'doSaveMenuFilter', null, function(so) {
            if (so.status == '1') {
                Alert(Sepoa.cache.text.get('MESSAGE.0001'));
            } else {
                Alert(so.msg);
            }
        });
    }
});
